@page "/recipes/{CuisineId:int}"
@using sv_eccd80f4f3a44194b8e39aa80b47bf78.Services
@rendermode InteractiveServer
@inject IRecipeService RecipeService
@inject ILogger<Recipes> Logger
@inject NavigationManager Navigation
@implements IDisposable

<PageTitle>Recipes</PageTitle>

<h1>Recipes</h1>

<nav>
    <a href="/recipes/1?sort=@Sort">Italian</a> |
    <a href="/recipes/2?sort=@Sort">Indian</a> |
    <a href="/recipes/3?sort=@Sort">Mexican</a>
</nav>

<div style="margin-top: 0.5rem;">
    <label>
        Sort:
        <select @onchange="OnSortChanged" value="@Sort">
            <option value="newest">Newest</option>
            <option value="popular">Popular</option>
        </select>
    </label>
</div>

@if (_error is not null)
{
    <div class="alert alert-danger" role="alert" style="margin-top: 1rem;">
        <p>@_error</p>
        <button class="btn btn-outline-danger" @onclick="Retry">Retry</button>
    </div>
}
else if (_recipes is null)
{
    <p style="margin-top: 1rem;"><em>Loading recipes...</em></p>
}
else
{
    @if (_isRefreshing)
    {
        <p style="margin-top: 0.5rem; font-style: italic; color: gray;">Refreshing…</p>
    }

    <ul style="margin-top: 1rem;">
        @foreach (var recipe in GetSortedRecipes())
        {
            <li>
                <strong>@recipe.Title</strong> — @recipe.Description
                <br /><small>Prep time: @recipe.PrepTimeMinutes min</small>
            </li>
        }
    </ul>
}

@code {
    [Parameter] public int CuisineId { get; set; }

    [SupplyParameterFromQuery(Name = "sort")]
    public string? Sort { get; set; }

    private List<Recipe>? _recipes;
    private string? _error;
    private bool _isRefreshing;
    private int _loadedCuisineId;
    private CancellationTokenSource? _cts;

    protected override async Task OnParametersSetAsync()
    {
        // Only reload when cuisine changes, not when sort changes
        if (CuisineId == _loadedCuisineId && _recipes is not null)
        {
            return;
        }

        await LoadRecipesAsync();
    }

    private async Task LoadRecipesAsync()
    {
        // Cancel any in-flight request
        _cts?.Cancel();
        _cts?.Dispose();
        _cts = new CancellationTokenSource();
        var token = _cts.Token;

        _error = null;
        _isRefreshing = _recipes is not null;

        try
        {
            var results = await RecipeService.GetByCuisineAsync(CuisineId, token);

            if (token.IsCancellationRequested)
            {
                return;
            }

            _recipes = results;
            _loadedCuisineId = CuisineId;
        }
        catch (OperationCanceledException)
        {
            // Request was cancelled (navigation away or new cuisine selected) — ignore
        }
        catch (TimeoutException ex)
        {
            Logger.LogError(ex, "Timeout loading recipes for cuisine {CuisineId}", CuisineId);
            _error = "The request timed out. Please try again.";
        }
        catch (Exception ex)
        {
            Logger.LogError(ex, "Error loading recipes for cuisine {CuisineId}", CuisineId);
            _error = "Something went wrong loading recipes. Please try again.";
        }
        finally
        {
            _isRefreshing = false;
        }
    }

    private List<Recipe> GetSortedRecipes()
    {
        if (_recipes is null) return new();

        return string.Equals(Sort, "popular", StringComparison.OrdinalIgnoreCase)
            ? _recipes.OrderBy(r => r.PrepTimeMinutes).ToList()
            : _recipes.OrderByDescending(r => r.Id).ToList();
    }

    private async Task Retry()
    {
        await LoadRecipesAsync();
    }

    private void OnSortChanged(ChangeEventArgs e)
    {
        var newSort = e.Value?.ToString() ?? "newest";
        Navigation.NavigateTo($"/recipes/{CuisineId}?sort={newSort}");
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
    }
}

